import AppKit

public enum NativeClipboard {
    public static func read(_ board: NSPasteboard) -> ClipContent? {
        let change = board.changeCount
        let excluded = Set([
            "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
            "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
        ])
        guard !(board.types ?? []).contains(where: { excluded.contains($0.rawValue) }) else {
            return nil
        }
        let value: ClipContent?
        if let urls = board.readObjects(
            forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
            !urls.isEmpty
        {
            value = .files(urls)
        } else if let data = board.data(forType: .png) {
            value = .image(data, "public.png")
        } else if let data = board.data(forType: .tiff) {
            value = .image(data, "public.tiff")
        } else {
            value = board.string(forType: .string).map(ClipContent.text)
        }
        return value.flatMap { change == board.changeCount && $0.valid ? $0 : nil }
    }
    public static func write(_ content: ClipContent, to board: NSPasteboard) throws {
        if case .files(let urls) = content,
            !urls.allSatisfy({ FileManager.default.fileExists(atPath: $0.path) })
        {
            throw ClipboardError.message("A source file moved or is unavailable. Copy it again.")
        }
        board.clearContents()
        let copied: Bool
        switch content {
        case .text(let text): copied = board.setString(text, forType: .string)
        case .image(let data, let type): copied = board.setData(data, forType: .init(type))
        case .files(let urls): copied = board.writeObjects(urls.map { $0 as NSURL })
        }
        if !copied { throw ClipboardError.message("Couldn't copy this clip. Try again.") }
    }
}

public enum ClipboardError: Error, LocalizedError {
    case message(String)
    public var errorDescription: String? {
        if case .message(let message) = self { return message }
        return nil
    }
}

public struct Snapshot {
    public let items: [Clip]
    public let paused: Bool
    public let error: String?
}

public final class ClipboardService {
    private let queue = DispatchQueue(label: "io.github.AK6.FeatherClip.clipboard", qos: .utility)
    private let history = History()
    private var timer: DispatchSourceTimer?
    private var lastChange = -1
    private let demo: Bool
    private var demoClipboard: ClipContent?
    public var onChange: (@MainActor (Snapshot) -> Void)?

    public init(demo: Bool) { self.demo = demo }
    public func start(image: Data?) {
        queue.async { [self] in
            if demo {
                if let image { history.insert(.image(image, "public.png")) }
                history.insert(.files([URL(fileURLWithPath: "/tmp/FeatherClip demo.txt")]))
                for text in [
                    "Hello from FeatherClip 👋", "A tiny home for the things you copy.",
                    "سلام! این یک کلیپ آزمایشی است.",
                ] { history.insert(.text(text)) }
                history.observe(nil)
            } else {
                poll()
            }
            publish()
            let timer = DispatchSource.makeTimerSource(queue: queue)
            timer.schedule(
                deadline: .now() + .milliseconds(750), repeating: .milliseconds(750),
                leeway: .milliseconds(100))
            timer.setEventHandler { [weak self] in self?.poll() }
            timer.resume()
            self.timer = timer
        }
    }
    private func poll(force: Bool = false) {
        guard !demo, !history.paused else { return }
        autoreleasepool {
            let board = NSPasteboard.general
            guard force || board.changeCount != lastChange else { return }
            lastChange = board.changeCount
            if history.observe(NativeClipboard.read(board)) { publish() }
        }
    }
    private func publish(error: String? = nil) {
        let snapshot = Snapshot(items: history.items, paused: history.paused, error: error)
        let callback = onChange
        DispatchQueue.main.async { callback?(snapshot) }
    }
    public func refresh() { queue.async { self.publish() } }
    public func togglePause() {
        queue.async {
            self.history.togglePause()
            self.poll(force: true)
            self.publish()
        }
    }
    public func clear() {
        queue.async {
            self.history.clear()
            self.poll(force: true)
            self.publish()
        }
    }
    public func copy(
        _ id: Int, completion: @escaping @MainActor (Result<ClipContent, Error>) -> Void
    ) {
        queue.async { [self] in
            guard let clip = history.items.first(where: { $0.id == id }) else {
                DispatchQueue.main.async {
                    completion(
                        .failure(ClipboardError.message("This clip is no longer in history.")))
                }
                return
            }
            do {
                if demo {
                    demoClipboard = clip.content
                } else {
                    try NativeClipboard.write(clip.content, to: .general)
                    lastChange = NSPasteboard.general.changeCount
                }
                history.copied(clip.content)
                publish()
                DispatchQueue.main.async { completion(.success(clip.content)) }
            } catch {
                publish(error: error.localizedDescription)
                DispatchQueue.main.async { completion(.failure(error)) }
            }
        }
    }
}
